For example, this Python validator rejects duplicate or unexpected parameters and validates values after normal URL decoding:

```python
import re
from urllib.parse import parse_qsl


class BadRequest(ValueError):
    pass


def strict_params(raw_query: bytes) -> dict[str, str]:
    try:
        query = raw_query.decode("ascii")
        pairs = parse_qsl(
            query,
            keep_blank_values=True,
            strict_parsing=True,
            max_num_fields=50,
        )
    except (UnicodeDecodeError, ValueError) as exc:
        raise BadRequest("Malformed query string") from exc

    allowed = {"q", "page"}
    result: dict[str, str] = {}

    for name, value in pairs:
        if name not in allowed:
            raise BadRequest("Unexpected parameter")
        if name in result:
            raise BadRequest("Duplicate parameter")
        result[name] = value

    if "q" in result and not 1 <= len(result["q"]) <= 100:
        raise BadRequest("Invalid q")

    if "page" in result:
        page = result["page"]
        if not re.fullmatch(r"[0-9]{1,4}", page):
            raise BadRequest("Invalid page")
        if not 1 <= int(page) <= 1000:
            raise BadRequest("Invalid page")

    return result
```

